function setupFeaturedRail(){const track=document.querySelector('#featuredTrack'),cards=[...track.querySelectorAll('.featured-slide')],count=document.querySelector('#featuredCount'),prev=document.querySelector('#featuredPrev'),next=document.querySelector('#featuredNext');if(!cards.length)return;const update=()=>{const center=track.scrollLeft+track.clientWidth/2;let best=0,delta=1e9;cards.forEach((x,i)=>{const d=Math.abs(x.offsetLeft+x.offsetWidth/2-center);if(d<delta){delta=d;best=i}});const changed=featuredActive!==best;featuredActive=best;if(changed)syncFeaturedStory();cards.forEach((x,i)=>{x.classList.toggle('is-active',i===best);if(i===best)x.setAttribute('aria-current','true');else x.removeAttribute('aria-current')});count.textContent=`${String(best+1).padStart(2,'0')} / ${String(cards.length).padStart(2,'0')}`;prev.disabled=best===0;next.disabled=best===cards.length-1};const go=i=>{const k=Math.max(0,Math.min(cards.length-1,i));track.scrollTo({left:cards[k].offsetLeft-(track.clientWidth-cards[k].offsetWidth)/2,behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})};prev.onclick=()=>go(featuredActive-1);next.onclick=()=>go(featuredActive+1);let raf=0;const scrolled=()=>{if(!raf)raf=requestAnimationFrame(()=>{raf=0;update()})};track.addEventListener('scroll',scrolled,{passive:true});const observer=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting)e.target.classList.add('is-revealed')}),{threshold:.13});cards.forEach(c=>observer.observe(c));featuredRailDispose=()=>{observer.disconnect();track.removeEventListener('scroll',scrolled);if(raf)cancelAnimationFrame(raf)};requestAnimationFrame(update)}
