function applyInitialRoute(){const params=new URLSearchParams(location.search);const product=params.get('producto'),exact=params.get('id'),menu=params.get('menu'),collection=params.get('coleccion');if(product||exact){const id=exact&&products[exact]?exact:Object.keys(products).find(k=>slug(k)===product||slug(products[k]?.name||'')===product);if(id)openPageProduct(id,'replace')}else if(menu){const target=menu.toLowerCase()==='bebidas'?'Bebidas':['desayuno','almuerzo','cena'].includes(menu.toLowerCase())?menu[0].toUpperCase()+menu.slice(1).toLowerCase():'Todos';activeMeal=target;renderMeals();buildCatalog();document.querySelector('#catalogo')?.scrollIntoView({block:'start'})}else if(collection==='destacados'){document.querySelector('#destacados')?.scrollIntoView({block:'start'})}}
