async function loadCatalog(){statusNode.textContent='Conectando con el menú…';try{try{const r=await fetch('/api/product-details',{cache:'no-store'});if(!r.ok)throw Error();productDetails=await r.json();try{localStorage.setItem('noglimar-product-details',JSON.stringify(productDetails))}catch{}}catch{try{productDetails=JSON.parse(localStorage.getItem('noglimar-product-details')||'{}')}catch{productDetails={}}}const saved=localStorage.getItem('noglimar-catalog-cache');if(saved&&!Object.keys(products).length){products=JSON.parse(saved);buildCatalog();statusNode.textContent='Menú guardado en este dispositivo; verificando cambios…'}const api=await ensureFirebase();await Promise.race([new Promise((resolve,reject)=>api.onValue(api.ref(db,'menus'),snap=>{products=snap.val()||{};try{localStorage.setItem('noglimar-catalog-cache',JSON.stringify(products))}catch{}statusNode.textContent='';buildCatalog();const requested=new URLSearchParams(location.search).get('producto');const exact=new URLSearchParams(location.search).get('id'),selected=exact&&products[exact]?exact:Object.keys(products).find(k=>slug(k)===requested);if(selected)openPageProduct(selected,'replace');else applyInitialRoute();resolve()},reject)),timeout(15000)])}catch(err){if(Object.keys(products).length){statusNode.textContent='Mostrando el último menú guardado; precios sujetos a confirmación.';return}console.error('Menu startup failed',err);showLoadFailure(err.message==='timeout'?'El servicio del menú tardó demasiado o no está disponible. Inténtalo más tarde.':'No se pudo conectar con el menú. Comprueba tu conexión e inténtalo más tarde.')}}
