function renderProduct(p,id){const session=document.querySelector('#productSession'),photos=galleryFor(p);session.innerHTML=`<nav class="breadcrumbs" aria-label="Migas de pan"><a href="./" data-catalog>Inicio</a><i data-lucide="chevron-right"></i><a href="./#catalogo" data-catalog>Menú</a><i data-lucide="chevron-right"></i><span>${esc(p.name)}</span></nav><article class="product-session-card"><div class="product-session-hero"><button type="button" class="product-main-open" id="openProductGallery" aria-label="Ampliar fotos de ${esc(p.name)}"><img class="product-main-photo" id="productMainPhoto" src="${esc(photos[0]||'')}" alt="${esc(p.name)}"><span>Ampliar foto</span></button><div class="product-photo-gallery" role="group" aria-label="Fotos de ${esc(p.name)}">${photos.map((url,i)=>`<button type="button" class="product-photo-thumb ${i===0?'selected':''}" data-photo-index="${i}" aria-label="${i===0?'Foto principal':'Ver foto '+(i+1)} de ${esc(p.name)}" aria-pressed="${i===0}"><img src="${esc(url)}" alt="" loading="lazy"></button>`).join('')}</div></div><div class="product-session-copy"><span class="eyebrow">${esc(productDetails[id]?.kind==='drink'?'Bebida':p.meal||'')}</span><h1>${esc(p.name)}</h1><p class="product-session-description">${esc(p.description||'')}</p><div class="product-facts">${productDetails[id]?.servings?`<div><b>Porción o presentación</b><span>${esc(productDetails[id].servings)}</span></div>`:''}<div><b>Alérgenos</b><span>${esc(productDetails[id]?.allergens||'Información no especificada. Consulta con Noglimar antes de pedir.')}</span></div></div><section class="ingredients-block"><h2>Ingredientes</h2><ul id="ingredientList"></ul>${(p.ingredients||[]).length>5?'<button type="button" class="ingredients-more" id="ingredientsMore" aria-expanded="false">Ver todos los ingredientes</button>':''}</section><div class="product-session-price">${priceMarkup(p.price)}</div><div class="product-session-actions"><button class="button-dark" id="productAddToOrder" type="button">Añadir a mi selección <i data-lucide="plus"></i></button><button class="button-dark secondary-action" id="productShare" type="button">Compartir menú <i data-lucide="share-2"></i></button></div><p class="share-feedback" id="shareFeedback" aria-live="polite"></p></div></article><button class="back-to-catalog-button" id="backToCatalog" type="button"><i data-lucide="arrow-left"></i> Volver al catálogo</button>`;session.hidden=false;let selectedPhoto=0;const photoButton=session.querySelector('#openProductGallery');photoButton.onclick=()=>openPhotoViewer(photos,selectedPhoto,p.name);session.querySelectorAll('[data-photo-index]').forEach(btn=>btn.addEventListener('click',()=>{const main=session.querySelector('#productMainPhoto'),index=Number(btn.dataset.photoIndex);selectedPhoto=index;main.classList.add('photo-changing');window.setTimeout(()=>{main.src=photos[index];main.classList.remove('photo-changing')},120);session.querySelectorAll('[data-photo-index]').forEach((b,j)=>{b.classList.toggle('selected',j===index);b.setAttribute('aria-pressed',String(j===index))});main.alt=`${p.name}, foto ${index+1} de ${photos.length}`}));document.querySelectorAll('main>section:not(#productSession)').forEach(e=>e.hidden=true);document.querySelector('footer').hidden=true;const ingredients=p.ingredients||[];document.querySelector('#ingredientList').innerHTML=ingredients.slice(0,5).map(i=>`<li>${esc(i)}</li>`).join('')+(ingredients.length>5?'<li class="ingredient-ellipsis">…</li>':'');const expand=document.querySelector('#ingredientsMore');if(expand)expand.onclick=()=>{const expanded=expand.getAttribute('aria-expanded')==='true';document.querySelector('#ingredientList').innerHTML=(expanded?p.ingredients.slice(0,5):p.ingredients).map(i=>`<li>${esc(i)}</li>`).join('')+(expanded&&p.ingredients.length>5?'<li class="ingredient-ellipsis">…</li>':'');expand.setAttribute('aria-expanded',String(!expanded));expand.textContent=expanded?'Ver todos los ingredientes':'Ver menos ingredientes'};document.querySelectorAll('[data-catalog]').forEach(a=>a.onclick=e=>{e.preventDefault();backToCatalog()});document.querySelector('#backToCatalog').onclick=backToCatalog;document.querySelector('#productAddToOrder').onclick=()=>{basket.set(id,(basket.get(id)||0)+1);updateBasket();notify('Añadido a tu pedido')};document.querySelector('#productShare').onclick=async()=>{const u=new URL(productUrl(id),location.origin).href;try{if(navigator.share)await navigator.share({title:`${p.name} | Noglimar`,url:u});else{await navigator.clipboard.writeText(u);document.querySelector('#shareFeedback').textContent='Enlace del plato copiado.'}}catch(e){if(e.name!=='AbortError')document.querySelector('#shareFeedback').textContent=u}};icons();window.scrollTo({top:0,behavior:'smooth'})}
function openPhotoViewer(photos,index,name){if(!photos.length)return;const d=document.createElement('dialog');d.className='photo-viewer';d.setAttribute('aria-label','Galería de '+name);d.innerHTML=`<div class="viewer-frame"><div class="viewer-top"><span id="viewerCount"></span><button type="button" class="viewer-close" aria-label="Cerrar galería">×</button></div><div class="viewer-image-zone"><button type="button" class="viewer-prev" aria-label="Foto anterior">‹</button><img alt=""><button type="button" class="viewer-next" aria-label="Foto siguiente">›</button></div><p>Desliza o usa las flechas para ver más fotos</p></div>`;document.body.append(d);let current=index,startX=0;const img=d.querySelector('img'),count=d.querySelector('#viewerCount');function show(){img.src=photos[current];img.alt=`${name}, foto ${current+1} de ${photos.length}`;count.textContent=`${current+1} de ${photos.length}`;d.querySelector('.viewer-prev').disabled=photos.length<2;d.querySelector('.viewer-next').disabled=photos.length<2}function move(step){current=(current+step+photos.length)%photos.length;show()}d.querySelector('.viewer-close').onclick=()=>d.close();d.querySelector('.viewer-prev').onclick=()=>move(-1);d.querySelector('.viewer-next').onclick=()=>move(1);d.addEventListener('keydown',e=>{if(e.key==='ArrowLeft')move(-1);if(e.key==='ArrowRight')move(1)});const zone=d.querySelector('.viewer-image-zone');zone.addEventListener('touchstart',e=>{startX=e.changedTouches[0].clientX},{passive:true});zone.addEventListener('touchend',e=>{const delta=e.changedTouches[0].clientX-startX;if(Math.abs(delta)>45)move(delta<0?1:-1)},{passive:true});d.addEventListener('click',e=>{if(e.target===d)d.close()});d.addEventListener('close',()=>{d.remove();document.querySelector('#openProductGallery')?.focus()});show();d.showModal();d.querySelector('.viewer-close').focus()}
function backToCatalog(){history.pushState({},'',siteRoot.pathname+location.hash.replace(/#.*/,''));showCatalog();document.querySelector('#catalogo').scrollIntoView({behavior:'smooth'})}
function showCatalog(){document.querySelector('#productSession').hidden=true;document.querySelectorAll('main>section:not(#productSession)').forEach(e=>e.hidden=false);document.querySelector('#historia-destacados').hidden=featuredItems.length===0;document.querySelector('footer').hidden=false}
function updateBasket(){const n=[...basket.values()].reduce((a,b)=>a+b,0);document.querySelector('#cartCount').textContent=n}
function openBasket(){const rows=[...basket.entries()].map(([id,n])=>{const p=products[id];return p?`<div class="basket-row"><div><b>${esc(p.name)}</b><small>${n} × ${money(p.price)}</small></div><strong>${money(n*p.price)}</strong><div class="quantity-control"><button data-basket-id="${esc(id)}" data-step="-1" aria-label="Quitar una unidad">−</button><span>${n}</span><button data-basket-id="${esc(id)}" data-step="1" aria-label="Añadir una unidad">＋</button></div></div>`:''}).join('');const total=[...basket.entries()].reduce((s,[id,n])=>s+(products[id]?.price||0)*n,0);openDialog(`<span class="eyebrow">TU PEDIDO</span><h2 id="dialogTitle">${rows?'Tu selección':'Tu pedido está vacío'}</h2>${rows?`<div class="basket-list">${rows}</div><div class="totals"><span>Total de la selección</span><b>${money(total)}</b></div><p class="field-hint">El total definitivo se vuelve a calcular en el servidor con los precios del menú.</p><button class="button-dark wide-button" id="startCheckout" type="button">Continuar al pago <span>→</span></button>`:'<p>Explora el menú y añade platos a tu selección.</p>'}<button class="button-dark wide-button secondary-action" id="basketClose" type="button">Seguir viendo el menú</button>`);content.querySelector('#basketClose').onclick=closeDialog;content.querySelector('#startCheckout')?.addEventListener('click',checkoutForm);content.querySelectorAll('[data-basket-id]').forEach(b=>b.onclick=()=>{const id=b.dataset.basketId,n=(basket.get(id)||0)+Number(b.dataset.step);n?basket.set(id,n):basket.delete(id);updateBasket();openBasket()})}
let checkoutSettings=null;

const offlineDb=()=>new Promise((resolve,reject)=>{const r=indexedDB.open('noglimar-orders-v1',1);r.onupgradeneeded=()=>r.result.createObjectStore('orders',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});
async function saveOfflineOrder(uid,payload){const dbx=await offlineDb();return new Promise((resolve,reject)=>{const tx=dbx.transaction('orders','readwrite');tx.objectStore('orders').put({id:payload.idempotencyKey,uid,payload,createdAt:Date.now()});tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error)})}
async function readOfflineOrders(uid){const dbx=await offlineDb();return new Promise((resolve,reject)=>{const tx=dbx.transaction('orders','readonly'),r=tx.objectStore('orders').getAll();r.onsuccess=()=>resolve(r.result.filter(x=>x.uid===uid));r.onerror=()=>reject(r.error)})}
async function removeOfflineOrder(id){const dbx=await offlineDb();return new Promise((resolve,reject)=>{const tx=dbx.transaction('orders','readwrite');tx.objectStore('orders').delete(id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
let replayingOfflineOrders=false;async function replayOfflineOrders(){if(replayingOfflineOrders||!navigator.onLine||!auth?.currentUser)return;replayingOfflineOrders=true;try{const queued=await readOfflineOrders(auth.currentUser.uid);for(const item of queued){try{const token=await auth.currentUser.getIdToken(),r=await fetch('/api/orders',{method:'POST',headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json','Idempotency-Key':item.payload.idempotencyKey},body:JSON.stringify(item.payload)});if(r.ok){await removeOfflineOrder(item.id);window.dispatchEvent(new CustomEvent('noglimar-order-sent',{detail:{id:item.id}}))}else if(r.status===401)break;else if(r.status>=500)break;else{const problem=(await r.json().catch(()=>({}))).error||'No se pudo enviar';window.dispatchEvent(new CustomEvent('noglimar-order-error',{detail:{id:item.id,message:problem}}));notify(`La reserva ${item.id} no se pudo enviar: ${problem}`);break}}catch{break}}}finally{replayingOfflineOrders=false}}
if('serviceWorker'in navigator)navigator.serviceWorker.addEventListener('message',e=>{if(e.data?.type==='SYNC_QUEUED_ORDERS')replayOfflineOrders()});window.addEventListener('noglimar-order-sent',()=>notify('La reserva guardada fue recibida por el servidor.'));window.addEventListener('noglimar-order-error',e=>notify(`No se pudo enviar: ${e.detail?.message||'revisa tu reserva'}`));
window.addEventListener('online',()=>{setTimeout(replayOfflineOrders,1000);notify('Conexión restablecida; enviando reservas guardadas…')});window.addEventListener('focus',replayOfflineOrders);document.addEventListener('visibilitychange',()=>{if(!document.hidden)replayOfflineOrders()});

