async function compressReceipt(file){const bitmap=await createImageBitmap(file);if(bitmap.width*bitmap.height>18000000)throw Error('La imagen tiene dimensiones demasiado grandes.');const scale=Math.min(1,1400/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));const ctx=canvas.getContext('2d');ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();let blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.78));if(!blob||blob.size>250*1024)blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.56));if(!blob||blob.size>250*1024)throw Error('No se pudo comprimir la imagen por debajo de 250 KB. Prueba con una captura más pequeña.');const bytes=new Uint8Array(await blob.arrayBuffer());let s='';for(let i=0;i<bytes.length;i+=0x8000)s+=String.fromCharCode(...bytes.subarray(i,i+0x8000));return {mime:'image/jpeg',data:btoa(s).replace(/=/g,'').replace(/\+/g,'-').replace(/\//g,'_')}}
