const originalUpdateBasket=updateBasket;
function updateBasket(){const n=[...basket.values()].reduce((a,b)=>a+b,0);document.querySelector('#cartCount').textContent=n}
function openDialog(html){if(receiptPreviewUrl){URL.revokeObjectURL(receiptPreviewUrl);receiptPreviewUrl=''}content.innerHTML=html;overlay.hidden=false;document.body.classList.add('dialog-open');icons();document.querySelector('#closeDialog').focus()}
function caracasDate(d=new Date()){return new Intl.DateTimeFormat('en-CA',{timeZone:'America/Caracas',year:'numeric',month:'2-digit',day:'2-digit'}).format(d)}
function parseRateDate(iso){if(!/^\d{4}-\d{2}-\d{2}$/.test(iso))return null;const d=new Date(`${iso}T12:00:00-04:00`);return Number.isNaN(d.valueOf())||d.toISOString().slice(0,10)!==iso?null:d}
function syncRateDialog(){const usd=document.querySelector('#rateUsdInput'),ves=document.querySelector('#rateVesInput');if(!officialRate){document.querySelector('#rateQuote').textContent='La tasa no está disponible';document.querySelector('#rateDate').textContent='';return}document.querySelector('#rateDialogTitle').textContent=officialRate.isToday?'Tasa del día':'Última actualización';document.querySelector('#rateQuote').textContent=`${officialRate.value.toLocaleString('es-VE',{minimumFractionDigits:4,maximumFractionDigits:4})} VES por USD`;document.querySelector('#rateDate').textContent=`Fecha de la tasa: ${officialRate.date}`;if(document.querySelector('#rateDialog').open){if(document.activeElement===ves&&ves.value)usd.value=String(Number(ves.value)/officialRate.value);else if(usd.value)ves.value=String(Math.round(Number(usd.value)*officialRate.value*100)/100)}}
async function loadRate(){const label=document.querySelector('#rateLabel'),value=document.querySelector('#rateValue');try{const r=await fetch('https://rates.dolarvzla.com/bcv/current.json',{cache:'no-store',headers:{Accept:'application/json'},signal:AbortSignal.timeout(9000)});if(!r.ok)throw Error();const data=await r.json(),today=caracasDate(),latest=[data.current,data.previous].filter(x=>parseRateDate(String(x?.date||''))&&x.date<=today&&Number.isFinite(Number(x.usd))&&Number(x.usd)>0&&Number(x.usd)<1e9).sort((a,b)=>b.date.localeCompare(a.date))[0];if(!latest)throw Error();const age=Math.round((parseRateDate(today)-parseRateDate(latest.date))/86400000);if(age<0||age>7)throw Error();officialRate={value:Number(latest.usd),date:latest.date,isToday:latest.date===today};label.textContent=officialRate.isToday?'Tasa del día':'Última actualización';value.textContent=`${officialRate.value.toLocaleString('es-VE',{minimumFractionDigits:2,maximumFractionDigits:2})} VES/USD`;document.querySelector('#rateOpen').setAttribute('aria-label',`${label.textContent}: ${officialRate.value} bolívares por dólar, fecha ${latest.date}`)}catch{officialRate=null;label.textContent='Tasa no disponible';value.textContent='';document.querySelector('#rateOpen').setAttribute('aria-label','Tasa USD/VES no disponible')}syncRateDialog();buildCatalog()}
document.querySelector('#rateOpen').addEventListener('click',()=>{const dlg=document.querySelector('#rateDialog');if(officialRate){document.querySelector('#rateUsdInput').value='1';document.querySelector('#rateVesInput').value=String(Math.round(officialRate.value*100)/100)}syncRateDialog();dlg.showModal()});document.querySelector('#rateUsdInput').addEventListener('input',()=>{const x=Number(document.querySelector('#rateUsdInput').value);document.querySelector('#rateVesInput').value=officialRate&&document.querySelector('#rateUsdInput').value!==''&&Number.isFinite(x)&&x>=0?String(Math.round(x*officialRate.value*100)/100):''});document.querySelector('#rateVesInput').addEventListener('input',()=>{const x=Number(document.querySelector('#rateVesInput').value);document.querySelector('#rateUsdInput').value=officialRate&&document.querySelector('#rateVesInput').value!==''&&Number.isFinite(x)&&x>=0?String(Math.round(x/officialRate.value*10000)/10000):''});loadRate();setInterval(loadRate,300000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)loadRate()});document.querySelector('#rateDialog').addEventListener('close',()=>{document.querySelector('#rateUsdInput').value='';document.querySelector('#rateVesInput').value=''})
