function refreshAccountButton(){const adminShortcut=document.querySelector('#adminShortcut');if(adminShortcut)adminShortcut.hidden=currentAccount?.uid!=='Wl0RHREv7AW7yrWC15xCGMm9YwL2';const b=document.querySelector('#loginOpen');if(b)b.innerHTML=currentAccount?`Mi cuenta <i data-lucide="user-round-check"></i>`:`Entrar <i data-lucide="user-round"></i>`;icons()}

function customConfirm(message){return new Promise(resolve=>{const modal=document.createElement('dialog');modal.className='site-confirm';modal.setAttribute('aria-label','Confirmar acción');const box=document.createElement('div');box.className='site-confirm-card';const text=document.createElement('p');text.textContent=message;const buttons=document.createElement('div');buttons.className='site-confirm-actions';const cancel=document.createElement('button'),ok=document.createElement('button');cancel.type=ok.type='button';cancel.textContent='Cancelar';ok.textContent='Confirmar';cancel.className='site-confirm-cancel';ok.className='site-confirm-ok';buttons.append(cancel,ok);box.append(text,buttons);modal.append(box);document.body.append(modal);let done=false;function finish(v){if(done)return;done=true;modal.close();modal.remove();resolve(v)}cancel.onclick=()=>finish(false);ok.onclick=()=>finish(true);modal.addEventListener('cancel',e=>{e.preventDefault();finish(false)});modal.showModal();cancel.focus()})}

const customerOrderLabels={received:'Recibida · esperando confirmación',accepted:'Confirmada por el negocio',preparing:'En preparación',ready:'Lista para entrega o retiro',fulfilled:'Completada',cancelled:'Rechazada o cancelada'};const customerPaymentLabels={pending:'Pendiente de pago',pending_review:'Comprobante pendiente de revisión',verified:'Pago confirmado',rejected:'Pago rechazado'};
function customerOrderCard(o){const stages=[['received','Recibida'],['accepted','Confirmada'],['preparing','Preparación'],['ready','Lista'],['fulfilled','Completada']],idx=stages.findIndex(x=>x[0]===o.orderStatus),cancel=o.orderStatus==='cancelled';return `<article class="tracking-card"><div class="tracking-head"><b>Reserva #${esc(o.id)}</b><span>${esc(customerOrderLabels[o.orderStatus]||o.orderStatus)}</span></div><p>${(o.lines||[]).map(x=>`${esc(x.name)} × ${esc(x.quantity)}`).join('<br>')}</p><b>${money(o.totalCents/100)}</b>${cancel?'<p class="tracking-cancel">Esta reserva fue rechazada o cancelada. Contacta a Noglimar si necesitas ayuda.</p>':`<ol class="tracking-steps">${stages.map(([v,label],i)=>`<li class="${i<=idx?'done':''}" ${i===idx?'aria-current="step"':''}><span>${i<idx?'✓':i+1}</span>${label}</li>`).join('')}</ol>`}<small>Pago: ${esc(customerPaymentLabels[o.payment?.status]||o.payment?.status||'Pendiente')}</small></article>`}
function accountDialog(){const isAdmin=currentAccount?.uid==='Wl0RHREv7AW7yrWC15xCGMm9YwL2';openDialog(`<div class="account-view"><div class="account-brand"><img src="logo-noglimar.png" alt="" width="50" height="50"><div><span>NOGLIMAR</span><small>Antojos &amp; Guisos</small></div></div><span class="account-kicker">${currentAccount?'MI ESPACIO':'BIENVENIDO A CASA'}</span><h2 id="dialogTitle">${currentAccount?'Tu cuenta':'Qué gusto tenerte aquí'}</h2><p class="account-intro">${currentAccount?'Administra tus datos y revisa tus pedidos.':'Entra o crea tu cuenta para gestionar tus pedidos.'}</p>${currentAccount?`<div class="account-identity"><span class="account-avatar" aria-hidden="true">${esc((currentAccount.displayName||currentAccount.email||'N').slice(0,1).toUpperCase())}</span><div><b>${esc(currentAccount.displayName||'Tu cuenta')}</b><small>${esc(currentAccount.email||'')}</small></div><span class="account-role">${isAdmin?'Administradora':'Cliente'}</span></div>${isAdmin?`<a class="account-admin" href="/admin"><span><strong>Panel de administración</strong><small>Reservas, pagos y menú</small></span><span aria-hidden="true">→</span></a>`:''}<section class="account-section"><h3>Mis pedidos</h3><p>Consulta el estado de tus reservas.</p><button class="account-secondary" id="accountOrders" type="button">Ver mis pedidos <span aria-hidden="true">→</span></button><div id="myOrders" aria-live="polite"></div></section><details class="account-details"><summary>Datos de mi perfil</summary><form id="profileForm" class="account-form"><label>Nombre para mostrar<input name="displayName" maxlength="80" value="${esc(currentAccount.displayName||'')}" autocomplete="name"></label><button class="account-secondary" type="submit">Guardar nombre</button></form></details><details class="account-details"><summary>Seguridad y contraseña</summary><form id="passwordForm" class="account-form"><label>Nueva contraseña<input type="password" name="newPassword" minlength="8" maxlength="128" required autocomplete="new-password" placeholder="Mínimo 8 caracteres"></label><button class="account-secondary" type="submit">Cambiar contraseña</button></form></details><button class="account-logout" id="accountLogout" type="button">Cerrar sesión</button><button class="account-delete" id="deleteAccount" type="button">Eliminar mi cuenta</button>`:`<div class="auth-mode-tabs" role="group" aria-label="Tipo de acceso"><button type="button" class="auth-mode active" data-auth-mode="signin" aria-pressed="true">Iniciar sesión</button><button type="button" class="auth-mode" data-auth-mode="signup" aria-pressed="false">Crear cuenta</button></div><form id="customerAuthForm" class="account-form"><label>Correo electrónico<input name="email" type="email" required autocomplete="email" maxlength="254" placeholder="nombre@correo.com"></label><label>Contraseña<input name="password" type="password" required autocomplete="current-password" minlength="8" maxlength="128" placeholder="Escribe tu contraseña"></label><p id="authPasswordHint" class="account-hint" hidden>Usa al menos 8 caracteres para proteger tu cuenta.</p><button type="button" class="account-link" id="passwordReset">¿Olvidaste tu contraseña?</button><p id="loginFeedback" class="admin-feedback" role="status" aria-live="polite"></p><button class="account-primary" id="authSubmit" type="submit">Iniciar sesión <span aria-hidden="true">→</span></button><p class="account-footnote">Al continuar, aceptas las <a href="/legal#condiciones" target="_blank" rel="noopener">condiciones de uso</a> y el <a href="/legal#privacidad" target="_blank" rel="noopener">aviso de privacidad</a>.</p></form>`}</div>`);const f=content.querySelector('#customerAuthForm');if(!f){content.querySelector('#accountOrders').onclick=async()=>{const box=content.querySelector('#myOrders');const saved=await readOfflineOrders(auth.currentUser.uid).catch(()=>[]);const pending=saved.map(o=>`<article class="confirmation-card"><b>Reserva guardada en este dispositivo</b><small>Referencia: ${esc(o.id)}</small><small>Esperando envío; aún no confirmada. Si cambió el precio, consulta con Noglimar antes de volver a pedir.</small><button type="button" data-delete-queued="${esc(o.id)}">Eliminar reserva local</button></article>`).join('');box.innerHTML=pending+'<div id="submittedOrders"><p>Consultando reservas enviadas…</p></div>';box.querySelectorAll('[data-delete-queued]').forEach(b=>b.onclick=async()=>{if(await customConfirm('¿Eliminar esta reserva guardada en este dispositivo?')){await removeOfflineOrder(b.dataset.deleteQueued);content.querySelector('#accountOrders').click()}});try{const token=await auth.currentUser.getIdToken(),r=await fetch('/api/my/orders',{headers:{Authorization:`Bearer ${token}`},cache:'no-store'}),arr=await r.json();if(!r.ok)throw Error(arr.error);box.querySelector('#submittedOrders').innerHTML=arr.length?arr.map(customerOrderCard).join(''):'<p>No tienes pedidos enviados todavía.</p>'}catch{box.querySelector('#submittedOrders').innerHTML='<p>No se pudieron consultar las reservas enviadas. Vuelve a intentar.</p>'}};content.querySelector('#profileForm').onsubmit=async e=>{e.preventDefault();try{const a=await ensureFirebase();await a.updateProfile(auth.currentUser,{displayName:content.querySelector('[name=displayName]').value.trim()});currentAccount=auth.currentUser;notify('Nombre actualizado.');accountDialog()}catch{notify('No se pudo actualizar el nombre.')}};content.querySelector('#passwordForm').onsubmit=async e=>{e.preventDefault();const value=content.querySelector('[name=newPassword]').value;if(value.length<8){notify('La contraseña debe tener al menos 8 caracteres.');return}try{const a=await ensureFirebase();await a.updatePassword(auth.currentUser,value);notify('Contraseña actualizada.');accountDialog()}catch{notify('Vuelve a iniciar sesión para cambiar la contraseña.')}};content.querySelector('#deleteAccount').onclick=async()=>{if(!await customConfirm('¿Eliminar tu cuenta permanentemente?'))return;try{const a=await ensureFirebase();await a.deleteUser(auth.currentUser);currentAccount=null;notify('Cuenta eliminada.');closeDialog()}catch{notify('Vuelve a iniciar sesión para confirmar la eliminación.')}};content.querySelector('#accountLogout').onclick=async()=>{try{await ensureFirebase();const api=await ensureFirebase();await api.signOut(auth);notify('Sesión cerrada.');closeDialog()}catch{notify('No se pudo cerrar la sesión.')}};return}let mode='signin';content.querySelectorAll('[data-auth-mode]').forEach(btn=>btn.onclick=()=>{mode=btn.dataset.authMode;content.querySelectorAll('[data-auth-mode]').forEach(x=>{x.classList.toggle('active',x===btn);x.setAttribute('aria-pressed',String(x===btn))});f.elements.password.autocomplete=mode==='signup'?'new-password':'current-password';content.querySelector('#authSubmit').innerHTML=mode==='signup'?'Crear mi cuenta <span aria-hidden="true">→</span>':'Iniciar sesión <span aria-hidden="true">→</span>';content.querySelector('#authPasswordHint').hidden=mode!=='signup';content.querySelector('#dialogTitle').textContent=mode==='signup'?'Crea tu cuenta':'Qué gusto tenerte aquí';content.querySelector('.account-intro').textContent=mode==='signup'?'Crea tu cuenta para gestionar tus pedidos.':'Entra o crea tu cuenta para gestionar tus pedidos.';content.querySelector('#passwordReset').hidden=mode==='signup';content.querySelector('#loginFeedback').textContent=''});content.querySelector('#passwordReset').onclick=async()=>{const email=f.elements.email.value.trim();if(!email){content.querySelector('#loginFeedback').textContent='Escribe tu correo para recibir instrucciones.';return}try{const a=await ensureFirebase();await a.sendPasswordResetEmail(auth,email);content.querySelector('#loginFeedback').textContent='Si el correo existe, recibirás instrucciones para restablecer tu contraseña.'}catch{content.querySelector('#loginFeedback').textContent='No se pudo enviar la solicitud.'}};f.addEventListener('submit',async e=>{e.preventDefault();const submit=content.querySelector('#authSubmit'),feedback=content.querySelector('#loginFeedback');submit.disabled=true;feedback.textContent='';try{const api=await ensureFirebase(),email=f.elements.email.value.trim(),password=f.elements.password.value;if(password.length<8)throw Error('La contraseña debe tener al menos 8 caracteres.');if(mode==='signup'){await api.createUserWithEmailAndPassword(auth,email,password);feedback.textContent='Cuenta creada e inicio de sesión listo.'}else{await api.signInWithEmailAndPassword(auth,email,password);feedback.textContent='Sesión iniciada.'}closeDialog()}catch(err){const code=err.code||'';feedback.textContent=code.includes('email-already-in-use')?'No se pudo crear la cuenta con esos datos.':code.includes('weak-password')?'La contraseña no cumple los requisitos del servicio.':code.includes('too-many-requests')?'Demasiados intentos. Espera un momento e inténtalo de nuevo.':code.includes('invalid-credential')||code.includes('user-not-found')||code.includes('wrong-password')?'No se pudo iniciar sesión con esos datos.':err.message==='La contraseña debe tener al menos 8 caracteres.'?err.message:'No se pudo completar el acceso. Comprueba tu conexión e inténtalo de nuevo.'}finally{submit.disabled=false}})}
document.querySelector('#closeDialog').onclick=closeDialog;overlay.addEventListener('click',e=>{if(e.target===overlay)closeDialog()});document.querySelector('#cartOpen').onclick=openBasket;document.querySelector('#loginOpen').onclick=accountDialog;

document.querySelector('#shareMenu')?.addEventListener('click',async()=>{const key=activeMeal==='Todos'?'todos':activeMeal.toLowerCase(),title=activeMeal==='Todos'?'Menú completo | Noglimar':`${activeMeal} | Noglimar`,u=shareUrl(`/menu/${key}`,title);try{if(navigator.share)await navigator.share({title,url:u});else{await navigator.clipboard.writeText(u);notify('Enlace del menú copiado')}}catch(e){if(e.name!=='AbortError')notify('No se pudo compartir el enlace')}});document.querySelector('#searchInput').addEventListener('input',e=>{search=e.target.value.trim();buildCatalog()});
const trigger=document.querySelector('#sortSelect'),options=document.querySelector('#sortOptions');trigger.onclick=()=>{options.hidden=!options.hidden;trigger.setAttribute('aria-expanded',String(!options.hidden))};options.querySelectorAll('[data-sort]').forEach(b=>b.onclick=()=>{sortMode=b.dataset.sort;trigger.querySelector('.sort-current').textContent=sortMode;options.hidden=true;trigger.setAttribute('aria-expanded','false');buildCatalog()});document.addEventListener('click',e=>{if(!e.target.closest('.custom-select-wrap')){options.hidden=true;trigger.setAttribute('aria-expanded','false')}});
const siteNav=document.querySelector('.nav-links'),menuButton=document.querySelector('#menuBtn');function closeMobileNav(){siteNav.classList.remove('mobile-open');menuButton.setAttribute('aria-expanded','false');menuButton.setAttribute('aria-label','Abrir navegación')}menuButton.onclick=e=>{const open=e.currentTarget.getAttribute('aria-expanded')==='true';siteNav.classList.toggle('mobile-open',!open);menuButton.setAttribute('aria-expanded',String(!open));menuButton.setAttribute('aria-label',open?'Abrir navegación':'Cerrar navegación')};siteNav.querySelectorAll('a,button').forEach(a=>a.addEventListener('click',closeMobileNav));document.addEventListener('click',e=>{if(!siteNav.contains(e.target)&&!menuButton.contains(e.target))closeMobileNav()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMobileNav()});
