function syncFeaturedStory(){const item=featuredItems[featuredActive];if(!item)return;const img=document.querySelector('#featuredStoryImage');img.src=item.imageUrl;img.alt=item.name;document.querySelector('#featuredStoryName').textContent=item.name;document.querySelector('#featuredStoryPrice').textContent=money(item.price);document.querySelector('#featuredStoryKind').textContent=item.kind==='drink'?'Bebida destacada':`Destacado · ${item.meal||'menú'}`}
function setupFeaturedStory(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const section=document.querySelector('#historia-destacados'),rail=section?.querySelector('.featured-story-rail'),img=document.querySelector('#featuredStoryImage'),stage=section?.querySelector('.story-image'),bar=document.querySelector('#featuredStoryProgress');if(!section||!rail)return;let raf=0,active=false;const clamp=x=>Math.max(0,Math.min(1,x)),ease=x=>{x=clamp(x);return x*x*(3-2*x)},mix=(a,b,t)=>a+(b-a)*t;const keyframes=[{p:0,rx:-18,ry:27,rz:-7,s:.64,y:112,x:60,py:38,ps:1.2},{p:.46,rx:0,ry:0,rz:0,s:1,y:0,x:0,py:0,ps:1.08},{p:1,rx:11,ry:-15,rz:4,s:1.1,y:-43,x:-18,py:-26,ps:1.22}];let last=-1;function draw(){raf=0;if(!active)return;const rect=section.getBoundingClientRect(),range=Math.max(1,section.offsetHeight-innerHeight),p=clamp(-rect.top/range);let i=p<=.46?0:1,a=keyframes[i],b=keyframes[i+1],t=ease((p-a.p)/(b.p-a.p));for(const k of ['rx','ry','rz','s','y','x','py','ps']){const v=mix(a[k],b[k],t),prop=({'rx':'--story-rx','ry':'--story-ry','rz':'--story-rz','s':'--story-scale','y':'--story-y','x':'--story-x','py':'--story-photo-y','ps':'--story-photo-scale'})[k];stage.style.setProperty(prop,['rx','ry','rz'].includes(k)?`${v.toFixed(2)}deg`:['s','ps'].includes(k)?v.toFixed(3):`${v.toFixed(1)}px`)}bar.style.width=`${(p*100).toFixed(1)}%`;const step=p<.46?0:1;if(step!==last){last=step;const item=featuredItems[Math.min(featuredActive,featuredItems.length-1)];if(!item)return;document.querySelector('#featuredStoryStep').textContent=step?'02 / 02':'01 / 02';document.querySelector('#featuredStoryTitle').textContent=step?'Y el sabor se queda.':'Un plato. Una historia.';document.querySelector('#featuredStoryText').textContent=step?`${item.name} · ${item.kind==='drink'?'Bebida':item.meal||'Menú'} de Noglimar.`:'Descubre la selección de platos y bebidas de Noglimar.';document.querySelector('#featuredStoryKind').textContent=item.kind==='drink'?'Bebida destacada':'Del menú de '+(item.meal||'Noglimar');document.querySelector('#featuredStoryName').textContent=item.name;document.querySelector('#featuredStoryPrice').textContent=money(item.price)}}function schedule(){if(!raf)raf=requestAnimationFrame(draw)}const observer=new IntersectionObserver(([e])=>{active=e.isIntersecting;if(active)schedule()},{rootMargin:'80% 0px'});observer.observe(section);addEventListener('scroll',schedule,{passive:true});addEventListener('resize',schedule,{passive:true});featuredStoryDispose=()=>{observer.disconnect();removeEventListener('scroll',schedule);removeEventListener('resize',schedule);if(raf)cancelAnimationFrame(raf)}}
function setupPrivacyConsent(){const banner=document.querySelector('#cookieBanner'),dlg=document.querySelector('#privacyDialog'),key='noglimar-privacy-choice-v1';let saved=null;try{saved=JSON.parse(localStorage.getItem(key)||'null')}catch{}if(!saved){banner.hidden=false;document.body.classList.add('has-cookie-banner')}function save(value){try{localStorage.setItem(key,JSON.stringify({essential:true,analytics:false,marketing:false,choice:value,updatedAt:new Date().toISOString()}))}catch{}banner.hidden=true;document.body.classList.remove('has-cookie-banner');dlg.close()}document.querySelector('#cookieEssential').onclick=()=>save('essential');document.querySelector('#cookieAcceptAll').onclick=()=>save('essential');document.querySelector('#privacySettingsLink')?.addEventListener('click',e=>{e.preventDefault();dlg.showModal()});document.querySelector('#cookieSettings').onclick=()=>dlg.showModal();document.querySelector('#privacyNecessary').onclick=()=>save('essential');document.querySelector('#privacySave').onclick=()=>save('essential');document.querySelector('#privacyAll').onclick=()=>save('essential');document.addEventListener('privacy:settings',()=>dlg.showModal())}
setupPrivacyConsent();
